}

static inline struct kmem_cache *page_get_cache(struct page *page) /* <=== page_get_cache */ 
{
	page = compound_head(page);
	BUG_ON(!PageSlab(page));
	return (struct kmem_cache *)page->lru.next;
}

static slob_t *slob_next(slob_t *s) /* <=== slob_next */ 
{
	slob_t *base = (slob_t *)((unsigned long)s & PAGE_MASK);
	slobidx_t next;

	if (s[0].units < 0)
		next = -s[0].units;
	else
		next = s[1].units;
	return base+next;
}

void *__kmalloc(size_t size, gfp_t flags) /* <=== __kmalloc */ 
{
	struct kmem_cache *s;

	if (unlikely(size > PAGE_SIZE / 2))
		return (void *)__get_free_pages(flags | __GFP_COMP,
							get_order(size));

	s = get_slab(size, flags);

	if (unlikely(ZERO_OR_NULL_PTR(s)))
		return s;

	return slab_alloc(s, flags, -1, __builtin_return_address(0));
}

void *kmem_cache_alloc_node(struct kmem_cache *c, gfp_t flags, int node) /* <=== kmem_cache_alloc_node */ 
{
	void *b;

	if (c->size < PAGE_SIZE)
		b = slob_alloc(c->size, flags, c->align, node);
	else
		b = slob_new_page(flags, get_order(c->size), node);

	if (c->ctor)
		c->ctor(c, b);

	return b;
}

